    string wordToSearch;
    int lineNumber = 1;
    int wordCount = 0;

    // Prompt user for file name and word to search
    cout << "Enter the file name: ";
    cin >> fileName;

    cout << "Enter the word to search: ";
    cin >> wordToSearch;

    // Open file for reading
    ifstream file(fileName);

    // Check if file was successfully opened
    if (!file.is_open()) {
        cerr << "Error: Could not open file: " << fileName << endl;
        return 1;
    }

    // Read file line by line and count word occurrences
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(wordToSearch, pos)) != string::npos) {
            wordCount++;
            pos += wordToSearch.length();
        }
        lineNumber++;
    }

    // Close file
    file.close();

    // Display results
    cout << "Word \"" << wordToSearch << "\" appears " << wordCount << " times in " << fileName << endl;
    cout << "Found in " << lineNumber << " lines." << endl;

    return 0;
}
